function Dashboard() {
  const [selectedId, setSelectedId] = useState<string | null>(null);

  return (
    <div style={{ display: 'flex' }}>
      <ItemList
        selectedId={selectedId}
        onSelect={setSelectedId}
      />
      <ItemDetail
        itemId={selectedId}
        onClear={() => setSelectedId(null)}
      />
    </div>
  );
}

function ItemList({ selectedId, onSelect }: { selectedId: string | null; onSelect: (id: string) => void }) {
  return (
    <ul>
      {items.map((item) => (
        <li
          key={item.id}
          style={{ fontWeight: item.id === selectedId ? 'bold' : 'normal' }}
        >
          <button onClick={() => onSelect(item.id)}>{item.name}</button>
        </li>
      ))}
    </ul>
  );
}

function AppLayout({ children }: { children: ReactNode }) {
  const { theme, user } = useAppLogic();

  return (
    <ThemeProvider value={theme}>
      <AuthProvider value={user}>
        <header>{/* uses theme and user */}</header>
        <main>{children}</main>
        <footer>{/* uses theme and user */}</footer>
      </AuthProvider>
    </ThemeProvider>
  );
}

// Each child can still access theme and user directly
// via Context without receiving them through intermediate props.
